import type { ExpansionSpec } from './types';
import type { Spec } from '../author';
const refs:Record<string,[string,string]>={Anatomy:['OpenStax Anatomy and Physiology 2e; further reading','https://openstax.org/books/anatomy-and-physiology-2e/pages/preface'],Physiology:['OpenStax Anatomy and Physiology 2e; further reading','https://openstax.org/books/anatomy-and-physiology-2e/pages/preface'],Biochemistry:['Molecular Biology of the Cell, 4th edition; further reading','https://www.ncbi.nlm.nih.gov/books/NBK21054/'],Pathology:['Molecular Biology of the Cell, 4th edition; further reading','https://www.ncbi.nlm.nih.gov/books/NBK21054/']};
let number=0;
function q(subject:string,system:string,topic:string,difficulty:1|2|3,stem:string,options:Spec['options'],explanation:string,objective:string,closest:string):ExpansionSpec{
const reference=refs[subject];if(!reference)throw new Error('Unknown expansion subject: '+subject);
return {code:`op26x-${String(++number).padStart(4,'0')}`,concept:topic.toLowerCase().replace(/[^a-z0-9]+/g,'-'),reasoning:({1:'recognition',2:'application',3:'integration'} as const)[difficulty],difficultyReason:`${difficulty===1?'Identify the explicitly described structure or process':difficulty===2?'Apply one causal mechanism to the stated perturbation':'Combine independent findings to infer the intermediate mechanism'}: ${objective}`,evidenceNote:'Publisher or NIH indexed bibliographic identity and broad subject coverage checked. OpenStax action-potential chapter was readable; direct NCBI requests encountered human verification. Book-level further reading does not independently validate every option or vignette; no clinician review.',semanticReviewNote:`Compared with prior ${closest}; the new objective is ${objective.toLowerCase()}`,concerns:topic==='Granulation versus granuloma'?['Semantic duplicate of op26-0055: same granulation-tissue recognition key and morphology; quarantine pending independent review.']:[],question:{subject,system,topic,exam:'Step 1',difficulty,stem,options,explanation,objective,reference}};
}
export const specs:ExpansionSpec[]=[
q('Physiology','Nervous System','Absolute neuronal refractory period',2,'An isolated axon receives two strong electrical pulses in rapid succession. The second pulse fails during the action-potential peak. Which channel state explains this?',[
['Inactivated voltage-gated sodium channels','Inactivation prevents reopening until membrane repolarization occurs.'],['Open sodium leak channels','Leak conductance does not create an absolute refractory interval.'],['Closed potassium leak channels','Potassium leak closure does not prevent all sodium-channel activation.'],['Activated sodium-potassium pumps','Pump activity maintains gradients rather than setting this brief interval.']],
'Sodium channels open rapidly and then enter an inactivated state. Additional depolarization cannot reopen them immediately. Repolarization restores availability, explaining why stronger stimulation cannot overcome the absolute refractory period.','Explain why sodium-channel inactivation prevents immediate neuronal restimulation.','neuromuscular transmitter release'),
q('Physiology','Nervous System','Saltatory conduction failure',2,'An experimental lesion removes myelin from an axonal segment while leaving the axon intact. Action potentials propagate more slowly. Which electrical change contributes?',[
['Increased membrane capacitance','Loss of insulation increases the charge needed to change membrane voltage.'],['Reduced membrane capacitance','Myelin normally lowers capacitance; its removal produces the opposite.'],['Complete loss of intracellular resistance','Cytoplasmic resistance persists despite loss of external myelin.'],['Elimination of sodium gradients','A focal myelin lesion need not eliminate transmembrane ion gradients.']],
'Myelin increases membrane resistance and reduces capacitance. Removing it allows current leakage and requires more charge to depolarize the membrane. Less depolarizing current reaches the next node efficiently, slowing or blocking conduction.','Predict the electrical consequences of losing myelin insulation.','spinal cord tract localization'),
q('Physiology','Nervous System','Presynaptic calcium trigger',2,'A nerve terminal is depolarized normally, but extracellular calcium is briefly removed from the preparation. Which immediate event is most directly reduced?',[
['Evoked synaptic vesicle exocytosis','Calcium entry normally activates the vesicle fusion machinery.'],['Axonal sodium-channel opening','The propagated sodium current does not require calcium as its carrier.'],['Synthesis of all neuronal proteins','Protein synthesis is not the immediate calcium-triggered synaptic event.'],['Diffusion of already released transmitter','Extracellular diffusion does not require calcium-triggered vesicle fusion.']],
'An arriving action potential opens terminal voltage-gated calcium channels. Calcium binding to the release machinery triggers vesicle fusion. Removing calcium therefore lowers evoked transmitter release even when the presynaptic electrical signal remains intact.','Link terminal calcium entry to activity-dependent transmitter release.','vesicle-fusion toxin effects'),
q('Physiology','Nervous System','Temporal synaptic summation',1,'A neuron receives several small excitatory potentials from one synapse in rapid succession. Together they reach threshold. Which process is demonstrated?',[
['Temporal summation','Successive potentials overlap before the earlier responses decay.'],['Spatial summation','This requires inputs from different locations rather than one repeated input.'],['Axonal degeneration','Degeneration does not explain reversible addition of graded potentials.'],['Absolute refractoriness','That interval prevents action-potential reinitiation rather than adding inputs.']],
'Postsynaptic potentials are graded signals that decay over time. Rapid repetition at one synapse permits residual depolarization to add to subsequent responses. The combined voltage can reach the axonal threshold even when each individual input cannot.','Distinguish temporal summation from summation of separate spatial inputs.','neuromuscular transmission'),
q('Physiology','Nervous System','Postsynaptic chloride shunting',2,'An inhibitory synapse opens chloride channels near the resting potential. An excitatory input now produces less depolarization without marked hyperpolarization. Why?',[
['Reduced membrane resistance diverts excitatory current','Opening conductance shunts current and limits the resulting voltage change.'],['Complete depletion of intracellular ATP','ATP depletion is unnecessary for this immediate conductance effect.'],['Permanent destruction of excitatory receptors','An inhibitory conductance need not alter receptor numbers or integrity.'],['Increased axonal sodium equilibrium potential','Changing chloride conductance does not directly raise the sodium gradient.']],
'An inhibitory conductance can suppress excitation by increasing total membrane conductance. The same excitatory current then produces a smaller voltage change. This shunting effect can occur with little resting voltage change when the chloride reversal potential is nearby.','Explain inhibition by conductance shunting without large hyperpolarization.','neuronal excitation mechanisms'),
q('Physiology','Musculoskeletal','ATP binding and rigor',2,'A permeabilized skeletal muscle fiber has adequate calcium but no available ATP. Myosin remains attached to actin. Which normal cross-bridge step cannot occur?',[
['Myosin detachment after ATP binding','Binding fresh ATP reduces the affinity of myosin for actin.'],['Calcium binding to troponin C','This step is explicitly preserved by adequate calcium availability.'],['Formation of thick filaments','Existing thick filaments do not disassemble each contraction cycle.'],['Exposure of actin sites by tropomyosin movement','Calcium can expose sites even when myosin cannot detach.']],
'ATP binding to myosin permits release from actin. ATP hydrolysis subsequently energizes the head for another cycle. Without ATP, attached heads cannot detach normally, producing rigor despite calcium-dependent exposure of the binding sites.','Separate ATP-dependent myosin detachment from calcium-dependent site exposure.','troponin-mediated contraction'),
q('Physiology','Musculoskeletal','Smooth muscle calcium sensor',1,'A smooth muscle preparation contracts after calcium enters its cytoplasm. Which calcium-binding protein initiates activation of myosin light-chain kinase?',[
['Calmodulin','The calcium-calmodulin complex activates myosin light-chain kinase.'],['Troponin C','Smooth muscle lacks the troponin regulatory system used by skeletal muscle.'],['Dystrophin','Dystrophin links structural components rather than acting as this calcium sensor.'],['Titin','Titin provides elastic structural support rather than activating this kinase.']],
'Calcium binds calmodulin in smooth muscle. The complex activates myosin light-chain kinase, which phosphorylates the regulatory light chain and increases myosin ATPase activity. This differs from skeletal muscle regulation through the troponin-tropomyosin system.','Identify the calcium sensor that activates smooth muscle contraction.','skeletal troponin regulation'),
q('Physiology','Musculoskeletal','Motor unit recruitment',2,'During a gradual voluntary increase in grip force, low-threshold fatigue-resistant units fire before large high-force units. Which principle explains the sequence?',[
['Smaller motor neurons reach threshold first','Their higher input resistance permits a greater voltage response to similar current.'],['Largest axons always depolarize first voluntarily','Voluntary recruitment generally follows the size principle in the opposite order.'],['All muscle fibers share one motor neuron','Separate motor units permit graded force through recruitment.'],['Slow fibers cannot respond to neural input','Slow fibers are innervated and recruited during low-force activity.']],
'Smaller motor neurons generally have higher input resistance and reach firing threshold at lower synaptic drive. They activate smaller, fatigue-resistant motor units first. As drive rises, larger units join, increasing force while preserving economical low-force control.','Apply the motor-neuron size principle to voluntary force recruitment.','muscle calcium regulation'),
q('Physiology','Musculoskeletal','Muscle spindle stretch sensing',1,'A tendon tap briefly stretches a muscle and activates a sensory ending arranged in parallel with extrafusal fibers. Which receptor detects this initial stretch?',[
['Muscle spindle','Intrafusal fibers detect muscle length and changes in length.'],['Golgi tendon organ','This receptor lies in series and primarily signals tendon tension.'],['Pacinian corpuscle in skin','It detects vibration rather than serving as the muscle length receptor.'],['Motor end plate','The end plate receives motor output rather than detecting muscle stretch.']],
'Muscle spindles contain intrafusal fibers arranged parallel to force-producing extrafusal fibers. Stretch activates their sensory afferents and can initiate the stretch reflex. Golgi tendon organs instead monitor force transmitted through the tendon in series with muscle.','Identify the muscle spindle as the receptor for the stretch-reflex input.','peripheral motor nerve lesions'),
q('Physiology','Nervous System','Gamma motor drive',2,'During voluntary muscle shortening, gamma motor neurons contract the ends of intrafusal fibers. What is the principal benefit for sensory feedback?',[
['Maintaining spindle sensitivity during shortening','Intrafusal tension keeps the central sensory region responsive to stretch.'],['Directly generating most external muscle force','Extrafusal fibers provide the main force applied to the skeleton.'],['Silencing every Ia sensory afferent','Gamma activation supports rather than abolishes spindle afferent firing.'],['Replacing alpha motor neuron activity','Gamma innervation cannot substitute for extrafusal motor activation.']],
'When extrafusal fibers shorten, an unstimulated spindle can become slack. Gamma activation shortens the intrafusal ends and preserves tension in the sensory center. Alpha-gamma coordination therefore maintains useful length feedback throughout movement.','Explain how gamma activation preserves spindle feedback during contraction.','stretch receptor identification'),
q('Physiology','Nervous System','Photoreceptor light response',2,'A retinal rod is exposed to a flash of light after dark adaptation. Which immediate membrane response follows activation of its phototransduction cascade?',[
['Hyperpolarization from closure of cGMP-gated channels','Reduced cGMP closes inward-current channels in the outer segment.'],['Depolarization from opening sodium channels','Rod phototransduction initially decreases the dark inward current.'],['Increased glutamate release from the rod','Light hyperpolarization reduces release at the photoreceptor terminal.'],['Direct opening of chloride channels by photons','Photons activate opsin rather than directly opening these chloride channels.']],
'Activated rhodopsin stimulates transducin and phosphodiesterase, decreasing cGMP. Fewer cGMP-gated channels remain open, reducing the dark inward current. The rod hyperpolarizes and releases less glutamate rather than generating a conventional sodium action potential.','Trace light-induced cGMP reduction to rod hyperpolarization.','optic chiasm anatomy'),
q('Physiology','Nervous System','Hair cell potassium entry',2,'Bending a cochlear hair bundle toward its tallest stereocilia opens apical mechanosensitive channels. Which ion carries much of the depolarizing current from endolymph?',[
['Potassium entering the hair cell','Potassium-rich endolymph and the electrical gradient favor apical entry.'],['Potassium leaving the apical surface','The endolymphatic electrochemical conditions favor the opposite direction.'],['Chloride entering through sodium channels','These channels do not convert chloride into the principal excitatory current.'],['Calcium leaving the basolateral membrane','Basolateral calcium entry follows depolarization and supports transmitter release.']],
'Endolymph has unusually high potassium and a positive electrical potential relative to hair-cell cytoplasm. Opening apical channels allows potassium entry and depolarization. Basolateral calcium channels then promote transmitter release onto auditory afferents.','Explain why potassium entry depolarizes cochlear hair cells.','neuronal synaptic calcium trigger'),
q('Physiology','Nervous System','Horizontal semicircular canal sensing',2,'A healthy volunteer begins rotating the head to the left while looking at a fixed target. Which vestibular structure primarily detects the angular acceleration?',[
['Horizontal semicircular canal cristae','Endolymph movement deflects cupulae and signals horizontal rotation.'],['Utricular macula alone','The utricle primarily detects linear acceleration and head tilt.'],['Saccular macula alone','The saccule mainly detects vertical linear acceleration and gravity.'],['Cochlear organ of Corti','Cochlear hair cells detect sound rather than angular head acceleration.']],
'Semicircular canals detect angular acceleration by relative movement of endolymph and cupular deflection. The horizontal canals are most relevant to a horizontal head turn. Utricular and saccular maculae instead detect linear acceleration and static orientation relative to gravity.','Distinguish angular acceleration sensing from otolith functions.','cochlear transduction'),
q('Physiology','Nervous System','Olfactory primary afferents',1,'A nasal biopsy identifies neurons whose apical processes bear odorant receptors and whose axons enter the olfactory bulb. Where are these cell bodies normally located?',[
['Olfactory epithelium','Primary olfactory sensory neurons lie within the specialized nasal epithelium.'],['Trigeminal ganglion','Trigeminal neurons mediate other nasal sensations rather than primary olfaction.'],['Olfactory bulb mitral layer','Mitral cells receive olfactory input rather than bearing nasal receptor cilia.'],['Superior cervical ganglion','This sympathetic ganglion does not contain primary odorant receptor neurons.']],
'Primary olfactory receptor cells are bipolar neurons in the olfactory epithelium. Their ciliated apical processes sample odorants, and their axons traverse the cribriform plate to bulb glomeruli. Mitral cells are downstream projection neurons within the bulb.','Locate primary olfactory receptor neuronal cell bodies.','cranial nerve motor localization'),
q('Physiology','Endocrine','Posterior pituitary hormone synthesis',1,'A laboratory traces vasopressin-containing axons from hypothalamic nuclei into the posterior pituitary. Where is this peptide principally synthesized?',[
['Hypothalamic magnocellular neuronal cell bodies','Peptide synthesis occurs in cell bodies before axonal transport to terminals.'],['Posterior pituitary pituicytes','Pituicytes support axons but are not the principal vasopressin synthesis site.'],['Anterior pituitary gonadotrophs','Gonadotrophs synthesize gonadotropins rather than vasopressin.'],['Adrenal medullary chromaffin cells','These cells produce catecholamines rather than hypothalamic peptides.']],
'Vasopressin is synthesized in hypothalamic magnocellular neurons, especially in supraoptic and paraventricular nuclei. It is transported in axons to posterior pituitary terminals for storage and release. The posterior lobe therefore releases a hormone made mainly elsewhere.','Distinguish vasopressin synthesis from posterior pituitary release.','ADH collecting-duct response'),
q('Physiology','Endocrine','Pulsatile GnRH signaling',2,'A pituitary preparation receives continuous GnRH rather than physiologic pulses. After an initial rise, gonadotropin release declines. Which mechanism explains the sustained change?',[
['Desensitization of pituitary GnRH signaling','Continuous stimulation reduces gonadotroph responsiveness after the initial response.'],['Permanent conversion of LH into FSH','LH and FSH are distinct hormones rather than interconvertible stored forms.'],['Direct inhibition of gonadal aromatase by GnRH','This does not explain altered responsiveness in an isolated pituitary.'],['Increased sensitivity to every GnRH pulse','The exposure is continuous and eventually reduces sensitivity.']],
'Pituitary gonadotrophs normally interpret pulsatile GnRH input. Sustained nonpulsatile exposure initially stimulates release but subsequently desensitizes the receptor-signaling system. Gonadotropin output falls despite continued ligand exposure, illustrating the importance of temporal signaling patterns.','Explain gonadotroph desensitization during continuous GnRH exposure.','thyroid negative feedback'),
q('Physiology','Endocrine','Prolactin tonic inhibition',2,'A nonfunctioning sellar lesion interrupts hypothalamic input through the pituitary stalk. Mild hyperprolactinemia develops. Loss of which signal best explains it?',[
['Dopamine delivery to lactotrophs','Dopamine normally provides tonic inhibition of prolactin secretion.'],['Growth hormone delivery to lactotrophs','Growth hormone is not the tonic hypothalamic inhibitor of prolactin.'],['Oxytocin delivery to thyrotrophs','This pathway does not provide tonic control of lactotroph secretion.'],['FSH transport into the hypothalamus','FSH is a pituitary output rather than the inhibitory stalk signal.']],
'Unlike many anterior pituitary axes, prolactin secretion is restrained by tonic hypothalamic dopamine. Stalk interruption reduces portal delivery of this inhibitory signal. Prolactin can therefore rise even while secretion of other anterior pituitary hormones declines.','Link stalk interruption to loss of dopaminergic prolactin inhibition.','sellar mass visual-field findings'),
q('Physiology','Endocrine','Thyroid hormone binding proteins',3,'A person develops increased thyroxine-binding globulin without thyroid disease. At a new steady state total T4 is high but TSH is normal. Which free T4 pattern is expected?',[
['Within the normal range','Feedback restores free hormone despite increased circulating bound hormone.'],['Persistently markedly elevated','Sustained high free T4 would usually suppress TSH in an intact axis.'],['Undetectable despite normal TSH','An intact feedback axis would respond to a major free hormone deficit.'],['Equal to total T4 concentration','Only a small fraction of circulating T4 is normally unbound.']],
'More binding protein initially captures additional T4 and lowers its free fraction. An intact hypothalamic-pituitary-thyroid axis increases hormone production until free T4 returns near its set point. Total T4 remains elevated because the enlarged bound pool persists.','Integrate altered binding with normal feedback and free thyroid hormone.','primary thyroid failure feedback'),
q('Physiology','Endocrine','Peripheral T4 activation',1,'A tissue preparation converts thyroxine into a more active thyroid receptor ligand by outer-ring deiodination. Which product is being formed?',[
['Triiodothyronine','Outer-ring deiodination of T4 generates biologically active T3.'],['Reverse triiodothyronine','Inner-ring deiodination generates reverse T3, which has little thyroid activity.'],['Thyroglobulin','Thyroglobulin is a large storage protein rather than a deiodination product.'],['Thyroid-stimulating hormone','TSH is a pituitary glycoprotein rather than a T4 metabolite.']],
'Thyroxine has four iodine atoms and serves partly as a circulating precursor. Outer-ring deiodinases remove one iodine to generate T3, a more potent thyroid receptor ligand. Inner-ring removal instead produces reverse T3, an inactive metabolic pathway.','Distinguish activating outer-ring deiodination from reverse T3 formation.','thyroid hormone binding'),
q('Physiology','Endocrine','Adrenal cortical zonation',1,'An adrenal section shows a middle cortical zone composed of pale lipid-rich cells in cords. Which major steroid class is principally produced in this zone?',[
['Glucocorticoids','The zona fasciculata is the principal cortical source of cortisol.'],['Catecholamines','Catecholamines originate mainly in the adrenal medulla rather than cortex.'],['Mineralocorticoids','Aldosterone production is concentrated in the outer zona glomerulosa.'],['Melatonin','Melatonin is principally associated with the pineal gland.']],
'The zona fasciculata lies between glomerulosa and reticularis and produces glucocorticoids, predominantly cortisol. Its lipid-rich appearance reflects steroidogenic substrate stores. Aldosterone arises mainly in glomerulosa, whereas catecholamines come from medullary chromaffin cells.','Identify cortisol production in the zona fasciculata.','adrenal failure clinical pattern'),
q('Physiology','Endocrine','Cortisol permissive vascular action',2,'A vessel responds weakly to catecholamines after prolonged glucocorticoid deprivation. Which normal action of cortisol helps maintain its vascular responsiveness?',[
['Permissive support of adrenergic signaling','Glucocorticoids maintain components needed for effective catecholamine responses.'],['Conversion of arteries into veins','Cortisol changes signaling rather than the anatomic identity of vessels.'],['Removal of every vascular calcium channel','This would reduce contraction rather than support vascular reactivity.'],['Obligatory endothelial destruction','Normal cortisol action does not require vascular endothelial injury.']],
'Cortisol supports vascular responses to catecholamines through permissive effects on receptor and postreceptor systems. Deficiency can impair vasoconstriction. This differs from cortisol acting as a rapidly released catecholamine or directly creating each contraction.','Explain cortisol-dependent maintenance of catecholamine responsiveness.','primary adrenal insufficiency diagnosis'),
q('Physiology','Endocrine','Adrenal PNMT induction',2,'An experiment reduces local cortical blood delivery to the adrenal medulla while preserving oxygen supply. Which epinephrine synthesis enzyme loses glucocorticoid stimulation?',[
['Phenylethanolamine N-methyltransferase','PNMT converts norepinephrine into epinephrine and is stimulated by cortisol.'],['Thyroid peroxidase','This enzyme supports thyroid iodination rather than catecholamine synthesis.'],['Aromatase','Aromatase generates estrogens rather than converting norepinephrine.'],['Glucose-6-phosphatase','This metabolic enzyme does not catalyze epinephrine formation.']],
'Medullary blood arriving from the cortex contains high cortisol concentrations. Cortisol induces PNMT, which methylates norepinephrine to epinephrine. Reduced local cortisol exposure can diminish this stimulation even when medullary oxygenation remains adequate.','Connect cortical cortisol delivery with medullary PNMT expression.','adrenal cortical zonation'),
q('Physiology','Endocrine','Beta-cell glucose electrical coupling',2,'An isolated pancreatic beta cell metabolizes glucose, raising its ATP-to-ADP ratio. Which membrane event links metabolism to insulin granule release?',[
['Closure of ATP-sensitive potassium channels','Reduced potassium efflux depolarizes the cell and opens calcium channels.'],['Opening of ATP-sensitive potassium channels','Greater potassium efflux would oppose glucose-triggered depolarization.'],['Closure of all voltage-gated calcium channels','Calcium entry is required for normal stimulated granule exocytosis.'],['Immediate nuclear dissolution','Insulin release is regulated secretion rather than cell destruction.']],
'Glucose metabolism raises ATP, closing beta-cell ATP-sensitive potassium channels. Reduced outward potassium current depolarizes the membrane and opens voltage-gated calcium channels. Calcium entry triggers exocytosis, linking nutrient availability to insulin secretion.','Trace beta-cell ATP elevation through potassium-channel closure to calcium entry.','insulin target-cell GLUT4 translocation'),
q('Physiology','Endocrine','Glucagon target specificity',2,'During fasting, glucagon stimulates hepatic glucose output but has little direct glycogenolytic effect in skeletal muscle. Which explanation accounts for the difference?',[
['Muscle lacks a substantial functional glucagon receptor response','Muscle glycogen is regulated chiefly through other signals such as epinephrine.'],['Muscle never contains glycogen','Skeletal muscle stores glycogen as fuel for its own activity.'],['Hepatic glucagon receptors are nuclear receptors','Glucagon signals mainly through cell-surface G protein-coupled receptors.'],['Glucagon is produced only within muscle','Pancreatic alpha cells are the principal endocrine source of glucagon.']],
'Hepatic glucagon receptors promote glycogenolysis and gluconeogenesis. Skeletal muscle lacks a comparable direct glucagon response and uses other signals to mobilize glycogen. Receptor distribution therefore contributes to tissue-selective hormone action.','Explain liver versus muscle differences in direct glucagon responsiveness.','insulin secretion coupling'),
q('Physiology','Endocrine','Incretin enhancement of insulin',2,'Matched blood glucose profiles are produced by oral glucose and an intravenous infusion. Insulin secretion is greater after the oral load. Which mechanism explains this?',[
['Gut hormone enhancement of glucose-dependent insulin secretion','GIP and GLP-1 augment beta-cell secretion after nutrient ingestion.'],['Oral glucose bypasses beta cells entirely','The measured extra insulin still originates from pancreatic beta cells.'],['Intravenous glucose cannot reach the pancreas','Circulating glucose reaches pancreatic tissue by either administration route.'],['All insulin is made by intestinal epithelial cells','The gut supplies signals rather than the principal insulin-producing cells.']],
'Enteral nutrients trigger release of intestinal incretins. GIP and GLP-1 enhance glucose-dependent beta-cell secretion, so oral glucose evokes more insulin than a matched intravenous exposure. Controlling glucose concentrations isolates the additional gut-derived signal.','Explain the insulin difference between matched oral and intravenous glucose.','beta-cell electrical coupling'),
q('Physiology','Endocrine','Calcitriol intestinal transcription',2,'Intestinal epithelial cells are exposed to active vitamin D for several hours. Which change most directly supports increased transcellular calcium absorption?',[
['Increased expression of calcium transport proteins','Calcitriol regulates transcription of proteins involved in calcium transport.'],['Destruction of the apical brush border','Brush-border destruction would impair rather than support absorption.'],['Inhibition of all enterocyte transcription','Vitamin D receptor signaling changes rather than abolishes gene expression.'],['Conversion of calcium into phosphate','Calcium and phosphate are separate elements and are not interconverted.']],
'Calcitriol binds an intracellular nuclear receptor and alters transcription. Greater expression of calcium transport machinery supports movement from the intestinal lumen toward blood. This genomic effect differs from rapid channel insertion and does not chemically convert one mineral into another.','Apply nuclear receptor signaling to intestinal calcium transport.','renal PTH effects'),
q('Physiology','Endocrine','Growth hormone IGF-1 mediation',2,'Liver cells exposed to growth hormone secrete a peptide that promotes cartilage growth. Which mediator principally carries this growth-promoting signal?',[
['Insulin-like growth factor 1','Hepatic and local IGF-1 mediate many growth-promoting actions of growth hormone.'],['Calcitonin','Calcitonin is not the principal hepatic mediator of growth hormone effects.'],['Aldosterone','Aldosterone regulates electrolytes rather than cartilage growth signaling.'],['Secretin','Secretin regulates digestive secretion rather than somatic growth mediation.']],
'Growth hormone stimulates IGF-1 production in liver and other tissues. IGF-1 supports proliferation and cartilage growth and participates in feedback control. Growth hormone also has direct metabolic effects, so not every action is mediated through IGF-1.','Identify IGF-1 as a major mediator of growth hormone-dependent growth.','anterior pituitary feedback'),
q('Physiology','Endocrine','Leptin nutritional signaling',2,'After sustained loss of adipose mass, circulating leptin decreases. In an intact regulatory system, which hypothalamic response tends to defend energy stores?',[
['Increased hunger signaling','Lower leptin reduces the signal of energy sufficiency to hypothalamic circuits.'],['Permanent abolition of feeding behavior','Reduced leptin generally increases rather than eliminates the drive to eat.'],['Direct conversion of adipocytes into neurons','Energy regulation uses hormonal signals rather than this cell conversion.'],['Complete loss of intestinal absorption','Leptin change does not require destruction of intestinal absorptive capacity.']],
'Adipocytes secrete leptin in relation to energy stores and nutritional state. Falling leptin reduces hypothalamic signals of energy sufficiency and promotes hunger and energy conservation. Leptin resistance in common obesity means high levels do not guarantee appetite suppression.','Predict compensatory appetite signaling after loss of fat-derived leptin.','incretin meal signaling'),
q('Physiology','Endocrine','Melatonin circadian source',1,'A volunteer has a rise in circulating melatonin during the biological night under dim light. Which gland principally supplies this circulating timing signal?',[
['Pineal gland','Pineal melatonin secretion conveys information about the circadian dark phase.'],['Anterior pituitary','Its major outputs do not include the principal nocturnal melatonin signal.'],['Adrenal cortex','This tissue produces steroids rather than the main melatonin rhythm.'],['Parathyroid gland','Parathyroid output regulates mineral balance rather than the nocturnal signal.']],
'The pineal gland produces circulating melatonin with a rhythm coordinated by the central circadian system. Darkness permits the nocturnal rise, whereas light can suppress secretion. The hormone conveys circadian timing rather than serving as a direct measure of sleep depth.','Identify the pineal source of circulating nocturnal melatonin.','adrenal hormone zonation'),
q('Physiology','Gastrointestinal','Gastric apical proton pump',1,'A gastric gland contains a large mitochondria-rich cell with intracellular canaliculi. Which apical transport protein directly secretes hydrogen ions into the lumen?',[
['Hydrogen-potassium ATPase','Parietal-cell pumps exchange intracellular hydrogen for luminal potassium.'],['Sodium-glucose cotransporter','This transporter supports nutrient uptake rather than acid secretion.'],['Aquaporin 2','This regulated water channel participates in collecting-duct water handling.'],['Sodium-potassium-chloride cotransporter alone','This cotransporter is not the final apical gastric proton-secretory pump.']],
'Parietal cells use ATP to secrete acid through their apical hydrogen-potassium ATPase. Carbonic anhydrase supplies hydrogen ions while bicarbonate exits basolaterally. The final proton secretory step is active exchange at the canalicular membrane.','Identify the apical parietal-cell transporter responsible for acid secretion.','pancreatic bicarbonate secretion'),
q('Physiology','Gastrointestinal','Intrinsic factor B12 transport',2,'An adult loses gastric parietal-cell function but retains a normal terminal ileum. Which protein deficit directly impairs receptor-mediated vitamin B12 absorption?',[
['Intrinsic factor','The intrinsic factor-B12 complex is recognized by distal ileal receptors.'],['Pancreatic amylase','Amylase digests carbohydrate rather than forming the B12 uptake complex.'],['Pancreatic lipase','Fat digestion enzymes cannot substitute for intrinsic factor in B12 transport.'],['Pepsinogen alone','Loss of pepsinogen is not the defining missing ileal B12 carrier here.']],
'Parietal cells produce intrinsic factor, which binds vitamin B12 after earlier luminal processing. The complex supports receptor-mediated uptake in the terminal ileum. Normal ileal anatomy cannot fully compensate when the required gastric binding protein is absent.','Link gastric intrinsic factor production to ileal vitamin B12 uptake.','ileal bile salt recycling'),
q('Physiology','Gastrointestinal','Enteropeptidase activation cascade',2,'Pancreatic proteases enter the duodenum as inactive precursors. Which brush-border enzyme initiates the normal cascade by converting trypsinogen into trypsin?',[
['Enteropeptidase','This duodenal enzyme activates trypsinogen and begins the protease cascade.'],['Lactase','Lactase hydrolyzes lactose rather than activating protease zymogens.'],['Salivary amylase','Amylase acts on starch rather than initiating protease activation.'],['Carbonic anhydrase','This enzyme supports acid-base chemistry rather than zymogen cleavage.']],
'Enteropeptidase cleaves the activation peptide from trypsinogen at the intestinal surface. Active trypsin then activates more trypsinogen and other protease precursors. Inactive precursor secretion helps limit premature proteolysis within pancreatic tissue.','Identify the intestinal initiator of pancreatic protease activation.','pancreatitis clinical criteria'),
q('Physiology','Gastrointestinal','CCK biliary coordination',2,'Fatty acids enter the duodenum after a meal. Which coordinated cholecystokinin response most directly delivers stored bile into the intestinal lumen?',[
['Gallbladder contraction with sphincter of Oddi relaxation','These coordinated actions promote bile movement into the duodenum.'],['Gallbladder relaxation with sphincter contraction','This combination impedes rather than promotes stored bile delivery.'],['Permanent common bile duct closure','Duct closure prevents bile from reaching the intestinal lumen.'],['Inhibition of every pancreatic enzyme secretion','CCK normally stimulates pancreatic enzyme secretion as another digestive action.']],
'Intestinal nutrients, particularly fats and amino acids, stimulate CCK release. Coordinated gallbladder contraction and sphincter of Oddi relaxation promote bile delivery. Bile then supports lipid digestion and absorption rather than remaining stored behind a closed outlet.','Predict coordinated biliary responses to fat-induced CCK release.','secretin bicarbonate response'),
q('Physiology','Gastrointestinal','Motilin migrating motor complex',2,'A fasting volunteer shows periodic strong upper gastrointestinal contractions between meals. The pattern stops after eating. Which hormone is associated with this program?',[
['Motilin','Motilin participates in the fasting migrating motor complex.'],['Insulin as the sole direct pacemaker','Insulin is not the characteristic signal of this fasting motility pattern.'],['Calcitonin','Calcitonin is not the principal mediator of the migrating motor complex.'],['Thyroxine released only during fasting','Thyroxine does not serve as the meal-to-meal trigger described here.']],
'The migrating motor complex is an interdigestive motor pattern that clears residual upper gastrointestinal contents. Motilin is associated with its cyclic activity. Eating switches the gut toward a fed pattern adapted for mixing and processing newly ingested nutrients.','Associate motilin with the fasting migrating motor complex.','intestinal bicarbonate signaling'),
q('Physiology','Gastrointestinal','Receptive gastric relaxation',2,'During swallowing, the proximal stomach accommodates food with little initial rise in pressure. Which neural mechanism permits this receptive relaxation?',[
['Vagovagal reflex recruiting inhibitory enteric signaling','Vagal pathways coordinate smooth muscle relaxation through enteric transmitters.'],['Paralysis of every vagal fiber','Normal accommodation requires organized reflex control rather than paralysis.'],['Sustained maximal fundic contraction','Fundic contraction would raise pressure rather than accommodate the meal.'],['Direct skeletal motor supply to the fundus','Gastric smooth muscle uses autonomic and enteric rather than skeletal motor control.']],
'Proximal gastric accommodation allows storage of a meal without a large pressure rise. Vagal afferent and efferent pathways recruit inhibitory enteric signals, including nitric oxide. The response is active neural regulation of smooth muscle tone rather than structural failure.','Explain vagovagal coordination of proximal gastric accommodation.','fasting motility pattern'),
q('Physiology','Gastrointestinal','Lactase osmotic diarrhea',2,'An adult develops gas and loose stools after milk and improves when lactose is avoided. What luminal consequence of deficient brush-border lactase contributes to diarrhea?',[
['Unabsorbed osmotically active carbohydrate','Uncleaved lactose remains in the lumen and retains water.'],['Conversion of lactose into absorbed amino acids','Lactose is a carbohydrate and cannot be absorbed as amino acids.'],['Loss of all hepatic bile-acid synthesis','Lactase deficiency does not require hepatic bile-acid synthesis failure.'],['Intrinsic-factor destruction alone','Intrinsic-factor processing does not explain the selective lactose trigger.']],
'Lactase splits lactose into absorbable monosaccharides. Unabsorbed lactose retains luminal water and is fermented by colonic bacteria, producing gas. The specific food trigger therefore explains both diarrhea and bloating without requiring diffuse intestinal mucosal loss.','Connect selective lactase deficiency with osmotic retention and bacterial fermentation.','celiac villous injury'),
q('Physiology','Gastrointestinal','Chylomicron lymphatic export',2,'An enterocyte packages absorbed long-chain dietary fat into a large lipoprotein particle. Through which route does most newly packaged fat initially leave the intestine?',[
['Lacteals and intestinal lymphatics','Large chylomicrons enter lymph before joining systemic venous blood.'],['Direct portal entry as intact chylomicrons','These large particles do not use the usual direct portal uptake route.'],['Renal glomerular filtration','The kidney is not the initial drainage route from enterocytes.'],['Biliary canaliculi','Canaliculi transport hepatic bile rather than intestinal lipoprotein particles.']],
'Enterocytes esterify long-chain lipids and assemble chylomicrons containing apolipoprotein B-48. The particles enter lacteals and reach blood through lymphatic drainage. Shorter-chain fatty acids have greater access to direct portal transport and follow a different pattern.','Trace intestinal chylomicron export through lymphatic drainage.','bile salt recycling'),
q('Physiology','Gastrointestinal','Gastric alkaline tide',2,'After gastric acid secretion increases, venous blood leaving the stomach transiently contains more bicarbonate. Which parietal-cell event accounts for this finding?',[
['Basolateral bicarbonate exit with chloride entry','Bicarbonate generated alongside hydrogen is exported toward blood.'],['Apical bicarbonate as the main gastric acid','Luminal hydrogen and basolateral bicarbonate secretion create the pattern.'],['Conversion of plasma chloride into bicarbonate','The exchanged ions are chemically distinct rather than interconverted.'],['Complete carbonic anhydrase cessation','Bicarbonate generation depends partly on carbonic anhydrase chemistry.']],
'Carbon dioxide hydration in parietal cells generates hydrogen and bicarbonate ions. Hydrogen enters the gastric lumen while bicarbonate exits basolaterally in exchange for chloride. This paired transport creates the transient gastric venous alkaline tide accompanying acid secretion.','Explain the bicarbonate movement accompanying gastric acid secretion.','parietal proton pump identification'),
q('Physiology','Gastrointestinal','Butyrate colonocyte fuel',2,'Colonic bacteria ferment dietary fiber that escaped small-intestinal digestion. Which product is an important local oxidative energy source for colonocytes?',[
['Butyrate','This short-chain fatty acid is oxidized as a major colonocyte fuel.'],['Intact cellulose','Humans do not directly digest intact cellulose into an enterocyte fuel.'],['Unconjugated bilirubin','Bilirubin is not the principal fuel generated by fiber fermentation.'],['Intrinsic factor','Intrinsic factor is a gastric protein rather than a fermentation product.']],
'Fermentation of nondigested carbohydrates produces short-chain fatty acids such as acetate, propionate, and butyrate. Colonocytes use butyrate as an important fuel. This recovers energy from substrates that host digestive enzymes cannot directly break down.','Identify butyrate as a fermentation-derived colonocyte fuel.','lactose fermentation and diarrhea'),
q('Anatomy','Musculoskeletal','Palmar interosseous adduction',2,'A patient cannot hold paper between adjacent extended fingers, but thumb opposition is preserved. Weakness of which muscle group most directly explains the deficit?',[
['Palmar interossei','These ulnar-innervated muscles adduct fingers toward the middle digit.'],['Thenar opponens muscles','Thumb opposition depends on these muscles and is preserved here.'],['Extensor digitorum','This muscle extends rather than primarily adducts the fingers.'],['Flexor pollicis longus','This muscle flexes the thumb distal phalanx rather than adducting fingers.']],
'Palmar interossei adduct the digits and receive deep ulnar motor innervation. Failure to resist finger separation tests a function different from median-innervated thumb opposition. Preserved opposition therefore does not establish intact ulnar intrinsic hand function.','Associate impaired finger adduction with palmar interosseous weakness.','median nerve opposition deficit'),
q('Anatomy','Musculoskeletal','Posterior interosseous motor lesion',3,'Finger extension is weak after a deep forearm injury, but wrist extension persists with radial deviation. Cutaneous sensation is normal. Which nerve branch is injured?',[
['Posterior interosseous nerve','This motor radial branch supplies many finger extensors without cutaneous sensation.'],['Superficial radial nerve','This sensory branch does not explain the lost finger extension.'],['Ulnar nerve at the wrist','Ulnar injury compromises intrinsic hand rather than this extensor pattern.'],['Median palmar cutaneous branch','This sensory branch does not supply finger extensor muscles.']],
'The posterior interosseous nerve supplies many forearm extensors but no skin territory. Its injury weakens finger extension while sparing cutaneous sensation. Preserved radial wrist extension through spared muscles helps distinguish this from a more proximal radial lesion.','Integrate motor sparing and absent sensory loss to localize posterior interosseous injury.','common fibular versus root localization'),
q('Anatomy','Musculoskeletal','Obturator thigh adduction',2,'A pelvic lesion weakens hip adduction and causes limited medial thigh numbness. Knee extension and the patellar reflex remain normal. Which nerve is affected?',[
['Obturator nerve','It innervates most thigh adductors and a variable medial thigh skin area.'],['Femoral nerve','A major femoral lesion compromises quadriceps and the patellar reflex.'],['Superior gluteal nerve','This nerve supplies hip abductors rather than the principal adductors.'],['Common fibular nerve','This distal nerve affects ankle and toe movement rather than hip adduction.']],
'The obturator nerve traverses the obturator canal to supply most medial thigh adductors. Its lesion can cause adduction weakness with a limited sensory deficit. Preserved quadriceps function and patellar reflex distinguish the pattern from a substantial femoral lesion.','Localize isolated hip adduction weakness to the obturator nerve.','femoral quadriceps injury'),
q('Anatomy','Musculoskeletal','Superior gluteal pelvic stabilization',2,'When a patient stands on the right leg, the left side of the pelvis drops. Which right-sided muscle action is principally deficient in this maneuver?',[
['Hip abduction by gluteus medius and minimus','These muscles stabilize the pelvis on the weight-bearing side.'],['Knee extension by quadriceps','Quadriceps does not provide the main lateral pelvic stabilization.'],['Hip adduction by adductor longus','Adductors do not provide the principal opposing moment during this test.'],['Ankle inversion by tibialis posterior','This distal action does not directly support the opposite pelvic rim.']],
'In single-leg stance, stance-side gluteus medius and minimus generate an abduction moment preventing contralateral pelvic descent. Right-sided weakness therefore causes the left pelvis to drop. These muscles receive superior gluteal rather than femoral or obturator innervation.','Determine weak stance-side hip abductors from contralateral pelvic drop.','long thoracic scapular stabilization'),
q('Anatomy','Musculoskeletal','Tibial tarsal tunnel route',2,'Compression posterior to the medial malleolus produces plantar tingling with preserved ankle dorsiflexion. Which nerve passes through the compressed tunnel?',[
['Tibial nerve','The tibial nerve passes beneath the flexor retinaculum into plantar branches.'],['Deep fibular nerve','This nerve travels anteriorly and supplies first dorsal web-space sensation.'],['Superficial fibular nerve','This nerve supplies much of the dorsum rather than the sole.'],['Saphenous nerve','This cutaneous nerve does not supply the principal plantar territory.']],
'The tibial nerve travels behind the medial malleolus through the tarsal tunnel and divides into plantar branches. Compression can produce sole symptoms while sparing dorsiflexion. The latter remains mediated by anterior compartment muscles supplied through the deep fibular nerve.','Locate the tibial nerve within the tarsal tunnel.','common fibular foot drop'),
q('Anatomy','Nervous System','Corneal reflex efferent localization',3,'Touching either cornea produces a left blink but never a right blink. Sensation is reported from both corneas. Which right-sided pathway is most directly impaired?',[
['Facial motor output to orbicularis oculi','Facial motor fibers close the eyelid in the blink response.'],['Ophthalmic sensory input alone','Left blinking to right corneal stimulation demonstrates usable right afferent input.'],['Optic nerve retinal input','The corneal reflex uses trigeminal rather than optic afferents.'],['Oculomotor output to levator','Levator opens the lid rather than producing blink closure.']],
'Corneal sensation through the ophthalmic trigeminal division activates bilateral facial motor pathways. Right closure fails regardless of the side stimulated, while the left response confirms afferent conduction. This pattern localizes to the right facial efferent pathway.','Use bilateral stimulus responses to localize corneal reflex efferent dysfunction.','abducens eye movement deficit'),
q('Anatomy','Nervous System','Hypoglossal tongue deviation',2,'A unilateral tongue lesion causes right-sided wasting. On protrusion the tongue deviates rightward. Which muscle weakness most directly accounts for the deviation?',[
['Right genioglossus','The intact opposite genioglossus pushes the tongue toward the weak side.'],['Left genioglossus','Left lower motor weakness would tend to cause leftward deviation.'],['Right masseter','Masseter closes the jaw rather than principally protruding the tongue.'],['Left orbicularis oris','This facial muscle closes the lips rather than protruding the tongue.']],
'Genioglossus protrudes the tongue through hypoglossal motor innervation. Unilateral weakness permits the intact opposite muscle to push the tongue toward the lesion. Ipsilateral wasting supports a lower motor process rather than an isolated supranuclear control deficit.','Explain tongue deviation toward a lower motor hypoglossal lesion.','cranial ocular motor localization'),
q('Anatomy','Nervous System','Stylopharyngeus motor supply',1,'A dissection isolates a muscle descending from the styloid process into the pharyngeal wall. Which cranial nerve uniquely supplies stylopharyngeus?',[
['Glossopharyngeal nerve','Cranial nerve IX supplies stylopharyngeus as its major branchial motor target.'],['Hypoglossal nerve','Hypoglossal supplies most tongue muscles rather than stylopharyngeus.'],['Facial nerve','Facial motor fibers supply different branchial-arch derivatives.'],['Abducens nerve','Abducens supplies lateral rectus rather than pharyngeal muscles.']],
'Stylopharyngeus elevates the pharynx during swallowing and receives glossopharyngeal motor supply. Most other pharyngeal muscles receive vagal supply through the pharyngeal plexus. Recognizing this exception separates its innervation from both tongue and laryngeal motor pathways.','Identify glossopharyngeal motor innervation of stylopharyngeus.','recurrent laryngeal anatomy'),
q('Anatomy','Nervous System','Parotid otic ganglion relay',2,'A tracer follows glossopharyngeal parasympathetic fibers through the lesser petrosal nerve. In which ganglion do they synapse before reaching the parotid gland?',[
['Otic ganglion','Postganglionic fibers accompany the auriculotemporal nerve to the parotid.'],['Ciliary ganglion','This relay serves ocular parasympathetic targets rather than parotid secretion.'],['Pterygopalatine ganglion','This ganglion supplies lacrimal and nasal targets rather than the parotid.'],['Superior cervical ganglion','This is a sympathetic rather than parasympathetic relay.']],
'Glossopharyngeal preganglionic fibers traverse the tympanic plexus and lesser petrosal nerve to the otic ganglion. Postganglionic fibers then accompany the auriculotemporal branch of V3. The carrier nerve does not change their glossopharyngeal parasympathetic origin.','Trace parotid secretomotor fibers through the otic ganglion.','stylopharyngeus motor supply'),
q('Anatomy','Nervous System','Ciliary accommodation mechanics',1,'While focusing on nearby text, the lens becomes more rounded. Contraction of which structure reduces zonular tension to permit this increase in curvature?',[
['Ciliary muscle','Contraction reduces zonular tension and permits the elastic lens to round.'],['Superior oblique','This extraocular muscle rotates the globe rather than changing lens curvature.'],['Dilator pupillae','This iris muscle enlarges the pupil rather than releasing zonular tension.'],['Lateral rectus','Ocular abduction does not directly mediate lens accommodation.']],
'Ciliary muscle contraction reduces tension transmitted through the suspensory zonules. Lens elasticity then permits a rounder shape and greater refractive power for near vision. This parasympathetic mechanism is distinct from iris dilation or extraocular alignment.','Explain ciliary muscle control of lens accommodation.','optic chiasm visual fields'),
q('Anatomy','Cardiovascular','Thoracic duct venous termination',1,'A chyle-containing vessel ascends through the thorax and drains at the left root of the neck. Where does this thoracic duct normally enter the venous circulation?',[
['Left internal jugular-subclavian junction','The thoracic duct usually enters near the left venous angle.'],['Right coronary artery','The duct drains into venous rather than coronary arterial blood.'],['Portal vein inside the liver','Intestinal lymph normally reaches systemic rather than direct portal circulation.'],['Right femoral vein','The femoral vein is not the usual terminal site of the thoracic duct.']],
'The thoracic duct drains most body lymph into systemic venous blood near the left internal jugular-subclavian junction. Intestinal chylomicrons travel through this route. The right upper body generally has separate right lymphatic drainage rather than sharing the entire thoracic duct pathway.','Locate the usual thoracic duct termination at the left venous angle.','portal-systemic venous connections'),
q('Anatomy','Respiratory','Intercostal bundle costal groove',1,'An intercostal cross-section shows the principal vein, artery, and nerve sheltered in a rib groove. Along which rib margin does this main bundle normally travel?',[
['Inferior margin of the rib above','The main bundle occupies the costal groove beneath the superior rib.'],['Superior margin of the rib below only','Collateral branches occur there but this is not the main costal-groove bundle.'],['Anterior midline of the sternum','Intercostal bundles travel through spaces rather than along this single midline.'],['Central rib marrow cavity','The bundle lies along the rib rather than within its marrow cavity.']],
'The main intercostal neurovascular bundle lies in the inferior groove of the rib above an interspace. Its usual superior-to-inferior order is vein, artery, nerve. Collateral branches exist, so this relation is an anatomic guide rather than proof of a vessel-free procedural path.','Locate the principal intercostal neurovascular bundle.','phrenic motor supply'),
q('Anatomy','Gastrointestinal','Epiploic foramen posterior boundary',1,'A probe passes into the lesser sac through the epiploic foramen in an abdominal specimen. Which major vessel forms the immediate posterior boundary of this opening?',[
['Inferior vena cava','The vena cava lies immediately posterior to the epiploic foramen.'],['Superior mesenteric artery','This artery arises lower and is not the immediate posterior boundary.'],['Splenic artery','The splenic artery courses leftward rather than bounding this opening posteriorly.'],['Inferior mesenteric vein','This vein is not the major posterior boundary of the opening.']],
'The epiploic foramen connects greater and lesser peritoneal sacs. The hepatoduodenal ligament containing the portal triad forms its anterior boundary, while the vena cava lies behind it. The first duodenal portion and caudate liver lobe bound it inferiorly and superiorly.','Identify the inferior vena cava behind the epiploic foramen.','foregut arterial supply'),
q('Anatomy','Gastrointestinal','Portal triad posterior member',1,'A transverse section through the hepatoduodenal ligament shows the principal portal triad structures. Which structure generally occupies the posterior position?',[
['Portal vein','The portal vein is posterior to the bile duct and proper hepatic artery.'],['Common bile duct','The duct usually lies in the right anterior portion of the triad.'],['Proper hepatic artery','The artery usually lies left and anterior relative to the portal vein.'],['Cystic artery as the main posterior tube','The cystic artery is not the principal posterior portal triad member.']],
'The hepatoduodenal ligament contains the portal vein, proper hepatic artery, and bile duct. The portal vein generally lies posterior, while duct and artery lie anteriorly on the right and left. These relations describe the main ligament structures rather than every intrahepatic branch.','Recognize the portal vein as the posterior portal triad member.','portal-systemic collateral drainage'),
q('Anatomy','Gastrointestinal','Pectinate line somatic sensation',2,'A lesion just below the anal pectinate line produces sharp localized pain. Which nerve supply explains the prominent somatic sensation in this location?',[
['Inferior rectal branches of the pudendal nerve','Somatic fibers supply the anal canal inferior to the pectinate line.'],['Vagus nerve','Vagal afferents do not provide the lower anal canal somatic supply.'],['Pelvic visceral afferents alone','The sharp localization below the line is explained by somatic innervation.'],['Phrenic nerve','Phrenic sensory fibers do not innervate the anal canal.']],
'The pectinate line marks a developmental and neurovascular transition. Below it, inferior rectal branches of the pudendal nerve provide somatic sensation. Lesions there can cause sharp localized pain, unlike many lesions confined above the line with different sensory supply.','Associate lower anal canal pain with pudendal somatic innervation.','appendiceal pain migration'),
q('Anatomy','Gastrointestinal','Splenorenal pancreatic tail',1,'A dissection identifies the peritoneal fold connecting the spleen to the left kidney region. Which structure commonly travels within this splenorenal ligament?',[
['Tail of the pancreas','The pancreatic tail approaches the splenic hilum within this peritoneal fold.'],['Entire common bile duct','The bile duct travels in right hepatoduodenal structures rather than this fold.'],['Right ureter','The right ureter does not travel in the left splenorenal ligament.'],['Appendix','The appendix is associated with the cecal region rather than the splenic hilum.']],
'The splenorenal ligament contains splenic vessels and the pancreatic tail near the splenic hilum. The adjacent gastrosplenic fold instead contains short gastric and left gastro-omental vessels. Distinguishing these folds explains the close pancreatic relation to hilar splenic structures.','Locate the pancreatic tail in the splenorenal ligament.','celiac trunk foregut territory'),
q('Anatomy','Gastrointestinal','Secondary duodenal retroperitoneal fixation',2,'An anatomy specimen shows the second duodenal portion fixed against the posterior abdominal wall. Which developmental process best explains this normal position?',[
['Mesenteric fusion with posterior parietal peritoneum','Secondary fusion fixes much of the initially mesenteric duodenum posteriorly.'],['Failure of every midgut rotation event','Normal secondary fixation does not require a global rotation failure.'],['Persistence of a freely mobile mesentery','A free mesentery would oppose the fixed posterior relation.'],['Formation within the kidney capsule','The duodenum does not develop inside the renal capsule.']],
'Most duodenum becomes secondarily retroperitoneal when its mesentery fuses with the posterior abdominal wall. The fixation is acquired during development rather than implying an originally extraperitoneal origin. The proximal first portion retains greater mobility and intraperitoneal relations.','Explain secondary retroperitoneal fixation of most of the duodenum.','foregut arterial anatomy'),
q('Anatomy','Renal','Renal hilar anterior posterior order',1,'A normal renal hilum is viewed from the front. Which principal structure generally lies anterior to both the renal artery and the renal pelvis?',[
['Renal vein','The usual main hilar order from anterior to posterior is vein, artery, pelvis.'],['Renal pelvis','The pelvis is generally posterior to the major hilar vascular structures.'],['Ureter as the foremost hilar structure','The collecting system normally occupies a posterior rather than foremost position.'],['Adrenal medulla','Adrenal medulla is not part of the renal hilar sequence.']],
'The major renal hilar structures are commonly ordered vein, artery, and renal pelvis from anterior to posterior. Branching variants can alter details, but this describes the usual principal relation. The ureter continues inferiorly from the pelvis rather than occupying the anterior vascular plane.','Identify the renal vein as the usual anterior major hilar structure.','renal clearance physiology'),
q('Anatomy','Nervous System','Dorsal root sensory cell bodies',1,'A sensory fiber is traced from the skin toward the spinal cord. In which structure is its pseudounipolar primary sensory neuronal cell body normally located?',[
['Dorsal root ganglion','Primary somatic sensory cell bodies lie in a ganglion on the dorsal root.'],['Ventral horn','Ventral horn neurons principally provide lower motor output.'],['Sympathetic chain ganglion','This contains autonomic postganglionic rather than primary cutaneous cell bodies.'],['Anterior median fissure','The fissure is a groove rather than a neuronal ganglion.']],
'Primary somatic sensory neurons are pseudounipolar and reside in dorsal root ganglia. Peripheral processes receive sensory input and central processes enter through dorsal roots. Motor neurons instead have cell bodies in the ventral horn and leave through ventral roots.','Locate primary spinal somatic sensory neuronal cell bodies.','spinal tract crossing patterns'),
q('Anatomy','Nervous System','Accessory nerve shoulder shrug',2,'A lateral neck injury causes shoulder droop and weak shrugging. Elbow flexion and lateral shoulder sensation remain intact. Which nerve is most likely affected?',[
['Spinal accessory nerve','Its motor supply to trapezius supports shoulder elevation and scapular positioning.'],['Axillary nerve','Axillary injury chiefly affects deltoid and lateral shoulder sensation.'],['Musculocutaneous nerve','This nerve supplies elbow flexors rather than trapezius.'],['Median nerve','Median motor targets do not generate the principal shoulder shrug.']],
'The spinal accessory nerve supplies trapezius and is vulnerable in the posterior triangle. Loss of trapezius function produces weak shoulder elevation and droop. Preserved elbow flexion and lateral shoulder sensation help separate this motor pattern from other upper-limb lesions.','Localize weak shoulder shrug and droop to spinal accessory dysfunction.','long thoracic scapular winging'),
q('Anatomy','Nervous System','White ramus thoracolumbar restriction',1,'A diagram shows myelinated sympathetic preganglionic fibers entering a paravertebral ganglion through a white ramus. At which level is a white ramus normally present?',[
['T6','White rami accompany the thoracolumbar sympathetic outflow.'],['C2','Cervical ganglia receive ascending fibers rather than local white rami.'],['S4','Sacral parasympathetic outflow does not create a local sympathetic white ramus.'],['C7','Cervical spinal levels do not normally provide sympathetic white rami.']],
'Sympathetic preganglionic cell bodies arise in thoracolumbar segments, conventionally T1-L2. Their myelinated fibers enter the chain through white rami. Gray rami carry postganglionic fibers more widely, including cervical and sacral levels, so their distribution differs.','Distinguish restricted thoracolumbar white rami from widespread gray rami.','peripheral sensory ganglion localization'),
q('Biochemistry','General Principles','Enzyme positive cooperativity',2,'An enzyme shows a sigmoidal substrate-velocity curve. Binding at one subunit increases substrate affinity at others. Which property explains the shape?',[
['Positive cooperativity','Subunit interactions make subsequent substrate binding more favorable.'],['Destruction of every active site','Destroyed active sites cannot explain rising cooperative catalysis.'],['Independent identical binding sites','Independent sites do not generate positive binding cooperativity.'],['Zero-order behavior at all concentrations','Cooperativity does not imply substrate independence at every concentration.']],
'Allosteric interactions couple substrate binding among subunits. Initial binding favors conformations with higher affinity at remaining sites, producing a sigmoidal response. This differs from simple Michaelis-Menten kinetics with independent binding and a hyperbolic curve.','Recognize positive cooperativity from sigmoidal enzyme kinetics.','competitive enzyme inhibition'),
q('Biochemistry','General Principles','Ubiquitin proteasomal targeting',2,'A short-lived cytosolic regulatory protein receives a chain of small covalently attached proteins before selective degradation. Which tag commonly directs it to the proteasome?',[
['Polyubiquitin','Appropriate ubiquitin chains target many intracellular proteins for proteasomal degradation.'],['Mannose-6-phosphate','This signal directs many hydrolases toward lysosomes rather than proteasomes.'],['A terminal poly-A RNA tail','Poly-A tails modify RNA rather than tagging protein substrates.'],['A phospholipid bilayer','A membrane is not the small covalent protein chain used for this targeting.']],
'Ubiquitin is attached to selected substrates through an enzyme cascade. Certain polyubiquitin chains are recognized by the proteasome, which unfolds and degrades the protein. This cytosolic pathway differs from Golgi sorting of newly synthesized lysosomal hydrolases.','Distinguish ubiquitin-dependent proteasomal targeting from lysosomal enzyme sorting.','mannose-6-phosphate targeting'),
q('Biochemistry','General Principles','Signal recognition particle targeting',2,'A nascent secretory peptide exposes an amino-terminal signal sequence while still attached to a ribosome. Which complex directs the translating ribosome toward the rough ER?',[
['Signal recognition particle','SRP recognizes the signal peptide and targets the complex to ER machinery.'],['Spliceosome','The spliceosome removes RNA introns rather than targeting ribosomes to ER.'],['DNA polymerase','DNA polymerase replicates DNA rather than recognizing nascent peptide signals.'],['Centromere complex','Centromeric proteins organize segregation rather than secretory targeting.']],
'Signal recognition particle binds the emerging ER signal sequence and ribosome. Docking at the ER receptor and translocon supports cotranslational entry into the secretory pathway. The peptide therefore enters the ER while synthesis continues rather than completing freely in the cytosol.','Explain signal recognition particle targeting of secretory protein translation.','lysosomal hydrolase Golgi sorting'),
q('Biochemistry','General Principles','ER N-linked glycosylation',1,'A nascent secretory protein receives an oligosaccharide on an asparagine residue during entry into the endoplasmic reticulum. Which modification is occurring?',[
['N-linked glycosylation','N-linked sugars attach to the amide nitrogen of selected asparagine residues.'],['O-linked glycosylation on serine','O-linked sugars attach to hydroxyl groups rather than asparagine nitrogen.'],['DNA methylation','DNA modification does not add oligosaccharides to proteins.'],['Ubiquitin removal','Deubiquitination does not transfer an ER oligosaccharide to asparagine.']],
'N-linked glycosylation transfers a preassembled oligosaccharide to selected asparagines in the ER lumen. Trimming and remodeling continue through the secretory pathway. The chemistry differs from O-linked glycosylation at hydroxyl-bearing residues, much of which occurs in the Golgi.','Identify ER N-linked glycosylation at asparagine residues.','lysosomal carbohydrate sorting signal'),
q('Biochemistry','General Principles','ER disulfide folding environment',2,'A secreted protein forms stabilizing disulfide bonds, while its cytosolic counterpart remains reduced. Which environment particularly supports disulfide formation?',[
['Oxidizing ER lumen','The ER lumen and disulfide isomerases support cysteine oxidation and rearrangement.'],['Reducing cytosol','The cytosol generally favors reduced thiols rather than stable disulfides.'],['Core of genomic DNA','DNA is not the compartment for secretory protein folding.'],['Mature erythrocyte nucleus','Mature human erythrocytes lack a nucleus and secretory protein synthesis.']],
'Secretory proteins fold in the ER lumen, whose redox environment and disulfide isomerases favor formation and correction of disulfide bonds. The more reducing cytosol generally preserves cysteine thiols. Compartmental chemistry therefore influences protein tertiary structure.','Explain compartment-specific formation of secretory protein disulfide bonds.','collagen hydroxylation'),
q('Biochemistry','General Principles','Unfolded protein response attenuation',2,'Misfolded proteins accumulate in the ER and activate a response that phosphorylates eIF2alpha. Which immediate effect helps reduce the folding burden?',[
['Reduced global translation initiation','Lower protein synthesis reduces entry of newly made chains into the stressed ER.'],['Duplication of every chromosome','Genome replication does not directly reduce the folding burden.'],['Increased translation of every secretory protein','More incoming chains would aggravate the immediate folding load.'],['Destruction of every ER membrane','Normal adaptation does not require complete ER membrane elimination.']],
'ER stress activates the unfolded protein response. PERK-dependent eIF2alpha phosphorylation attenuates general translation, limiting new chains while adaptive chaperone programs respond. Prolonged unresolved stress can be injurious, but this initial reduction of synthesis is protective.','Explain translational attenuation during adaptive ER stress signaling.','secretory peptide targeting'),
q('Biochemistry','General Principles','LDL coated-pit internalization',2,'A receptor mutation preserves LDL binding at the cell surface but prevents clustering in coated pits. Which process is most directly impaired by the mutation?',[
['Receptor-mediated LDL internalization','Cytosolic sorting motifs recruit coated-pit machinery needed for uptake.'],['Initial extracellular LDL binding','The stem explicitly states that ligand binding is preserved.'],['Synthesis of every membrane phospholipid','A sorting-motif defect does not require global lipid synthesis failure.'],['Mitochondrial translation','LDL receptor uptake is not performed by mitochondrial ribosomes.']],
'LDL receptors bind extracellular particles and concentrate in clathrin-coated pits through cytoplasmic sorting information. A defective internalization motif can preserve binding while impairing uptake. The experiment therefore separates receptor recognition from subsequent vesicle formation and cargo entry.','Distinguish LDL surface binding from coated-pit internalization.','soluble lysosomal enzyme targeting'),
q('Biochemistry','General Principles','Endosomal receptor recycling',2,'An internalized receptor releases its ligand in an acidic endosome and returns to the cell surface. What advantage does this recycling pathway provide?',[
['Repeated uptake without replacing the receptor each cycle','Reusing receptors maintains ligand uptake while limiting new synthesis.'],['Permanent elimination of surface recognition','Recycling restores rather than abolishes functional surface receptors.'],['Conversion of receptor protein into cholesterol','The receptor is reused rather than converted chemically into its cargo.'],['Nuclear membrane rupture during each cycle','Endosomal recycling does not require nuclear envelope disruption.']],
'Endosomal acidification can separate receptors from their ligands. Sorting returns selected receptors to the plasma membrane while cargo follows a different route. Receptor reuse permits repeated uptake and differs from obligatory lysosomal degradation of the receptor itself.','Explain how endosomal recycling supports repeated receptor-mediated uptake.','initial clathrin internalization'),
q('Biochemistry','General Principles','Mitochondrial transcript translation',1,'A human cell makes a respiratory-chain polypeptide encoded by mitochondrial DNA. Which machinery directly translates the corresponding mitochondrial messenger RNA?',[
['Mitochondrial ribosomes','Mitochondrial transcripts are translated within the organelle by specialized ribosomes.'],['Cytosolic ribosomes exclusively','These translate nuclear transcripts rather than normal mitochondrial genome products.'],['Rough ER ribosomes','ER translation serves secretory pathways rather than mitochondrial transcripts.'],['Nucleolar RNA polymerase','RNA polymerases synthesize RNA rather than translating polypeptides.']],
'Human mitochondria retain a small genome encoding selected respiratory-chain proteins and their own rRNAs and tRNAs. Mitochondrial ribosomes translate these transcripts. Most mitochondrial proteins are nevertheless nuclear encoded, translated in the cytosol, and subsequently imported.','Identify the translation site for mitochondrially encoded polypeptides.','mitochondrial inheritance'),
q('Biochemistry','General Principles','Nuclear encoded mitochondrial import',2,'A matrix enzyme encoded by a nuclear gene contains an amino-terminal mitochondrial targeting sequence. On which machinery does its synthesis normally begin?',[
['Cytosolic ribosomes','Most nuclear-encoded mitochondrial proteins begin synthesis on cytosolic ribosomes.'],['Mitochondrial ribosomes exclusively','These chiefly translate the limited mitochondrial-genome coding set.'],['Golgi cisternae','Golgi compartments sort proteins rather than translating messenger RNA.'],['Lysosomal lumen','Lysosomes degrade substrates rather than serving as the usual translation site.']],
'Most mitochondrial proteins are nuclear encoded and synthesized by cytosolic ribosomes. Targeting sequences guide import through mitochondrial translocases, often with chaperone assistance. This pathway differs from organelle translation of the small set encoded directly in mitochondrial DNA.','Trace synthesis and targeting of a nuclear-encoded mitochondrial matrix protein.','mitochondrial transcript translation'),
q('Biochemistry','General Principles','Peroxisomal chain shortening',2,'Fibroblasts with defective peroxisome assembly accumulate very-long-chain fatty acids despite preserved mitochondrial structure. Which process is primarily impaired?',[
['Peroxisomal shortening of very-long-chain fatty acids','Peroxisomes process substrates that mitochondria handle poorly at their initial length.'],['Translation of every cytosolic protein','Selective lipid accumulation does not imply complete protein synthesis loss.'],['Direct conversion of fatty acids into DNA','No normal pathway directly converts these lipid chains into DNA molecules.'],['Mitochondrial glucose oxidation alone','The organelle defect and accumulated substrate point toward peroxisomal processing.']],
'Peroxisomes shorten very-long-chain fatty acids through oxidative metabolism. Products can undergo further metabolism in other compartments. Preserved mitochondria do not replace this peroxisomal contribution, so a biogenesis defect can cause characteristic lipid accumulation.','Connect very-long-chain fatty acid accumulation to peroxisomal processing failure.','carnitine-dependent mitochondrial lipid entry'),
q('Biochemistry','General Principles','Catalase peroxide decomposition',1,'An organelle generates hydrogen peroxide during oxidation and contains an enzyme that converts peroxide into water and oxygen. Which enzyme performs this reaction?',[
['Catalase','Catalase decomposes hydrogen peroxide and is abundant in peroxisomes.'],['Hexokinase','Hexokinase phosphorylates glucose rather than decomposing hydrogen peroxide.'],['DNA ligase','DNA ligase joins DNA ends rather than detoxifying peroxide.'],['Pepsin','Pepsin digests proteins in acidic gastric contents rather than disposing of peroxide.']],
'Peroxisomal oxidases transfer electrons to oxygen and can generate hydrogen peroxide. Catalase converts accumulated peroxide into water and oxygen, limiting oxidative injury. The reaction supports safe oxidative metabolism and differs from glucose phosphorylation or proteolysis.','Identify catalase-mediated peroxide disposal.','NADPH-dependent glutathione defense'),
q('Biochemistry','Nervous System','Kinesin axonal transport',2,'Fluorescent cargo moves from a neuronal cell body toward its distal terminal along axonal microtubules. Which motor family commonly drives this anterograde movement?',[
['Kinesin','Many kinesins transport cargo toward distally oriented microtubule plus ends.'],['Cytoplasmic dynein','Dynein commonly drives retrograde movement toward microtubule minus ends.'],['Myosin using actin only','Myosin is not the principal long-range microtubule motor described.'],['Histone H1','Histones organize chromatin rather than moving axonal cargo.']],
'Axonal microtubules are largely oriented with plus ends directed distally. Kinesin motors use ATP to move many cargoes toward these ends. Cytoplasmic dynein commonly supports return toward the cell body, distinguishing outward delivery from retrograde transport.','Associate kinesin with anterograde microtubule transport in axons.','synaptic vesicle release'),
q('Biochemistry','General Principles','Actin lamellipodial protrusion',2,'A migrating fibroblast extends a broad leading-edge sheet along the substrate. Which cytoskeletal process most directly generates this protrusive lamellipodium?',[
['Actin assembly near the leading membrane','Polymerizing branched actin networks push the cell membrane forward.'],['Nuclear chromosome condensation','Chromosome condensation serves division rather than leading-edge protrusion.'],['Loss of every adhesion molecule','Migration needs coordinated attachment and release rather than absent adhesion.'],['Assembly of rRNA into microtubules','Ribosomal RNA is not the structural subunit of the protrusive actin network.']],
'Lamellipodia contain dynamic branched actin networks. Subunit addition near the plasma membrane generates protrusion, while adhesions transmit traction to the substrate. Coordinated turnover and rear release then permit migration rather than merely changing volume.','Explain actin-driven lamellipodial extension during cell migration.','wound healing collagen deposition'),
q('Biochemistry','General Principles','Keratin tensile support',1,'An epithelial cell resists stretching through a durable filament network linked to desmosomes. Which filament type chiefly provides this junctional tensile support?',[
['Keratin intermediate filaments','Keratins link epithelial junctions and distribute mechanical stress.'],['Actin as the sole desmosomal scaffold','Desmosomes primarily anchor intermediate rather than actin filaments.'],['Bacterial flagellar filaments','Human epithelial junctions do not use bacterial flagella.'],['Nuclear chromatin','Chromatin does not form the cytoplasmic desmosomal support network.']],
'Intermediate filaments distribute mechanical loads across cells. Epithelial keratins connect with desmosomal and hemidesmosomal anchoring complexes, providing tensile resilience. This durable support differs from dynamic actin-based protrusion and from microtubule-based long-range cargo transport.','Identify keratin intermediate filaments as epithelial tensile support.','actin-driven migration'),
q('Biochemistry','General Principles','Claudin paracellular barrier',2,'A cell monolayer loses claudin organization and becomes more permeable between neighboring cells despite intact plasma membranes. Which pathway has become leakier?',[
['Paracellular pathway','Tight junctions regulate passage through the spaces between epithelial cells.'],['Mitochondrial matrix import','This intracellular transport route does not account for intercellular leakage.'],['Nuclear pore transport','Nuclear transport does not form the epithelial intercellular barrier.'],['Axonal anterograde transport','Axonal movement does not explain permeability across an epithelial sheet.']],
'Tight junctions regulate the route between adjacent epithelial cells. Claudins are major determinants of paracellular permeability and selectivity. Their disruption allows intercellular leakage while individual membranes may remain intact, distinguishing this from transcellular membrane damage.','Link claudin disruption to increased paracellular permeability.','receptor-mediated transcellular uptake'),
q('Biochemistry','General Principles','Connexin gap junction channels',2,'Dye injected into one cardiac cell reaches neighboring cells through channels spanning paired membranes. Which proteins form these intercellular communication channels?',[
['Connexins','Connexin assemblies form connexons that dock between adjacent cells.'],['Claudins','Claudins form tight-junction barriers rather than cytoplasmic communication pores.'],['Cadherins alone','Cadherins mediate adhesion but do not form the gap-junction aqueous pore.'],['Type I collagen','Matrix collagen does not create the membrane-spanning intercellular channel.']],
'Gap junctions consist of paired connexons assembled from connexins. They permit ions and selected small molecules to move between cells, supporting electrical and metabolic coupling. Their communication function differs from tight-junction sealing and desmosomal mechanical attachment.','Identify connexins as gap-junction channel subunits.','tight junction permeability'),
q('Biochemistry','General Principles','Integrin matrix linkage',2,'Blocking a fibroblast surface receptor for fibronectin alters its shape and traction. Which receptor family normally couples extracellular matrix binding to cytoskeletal signaling?',[
['Integrins','These heterodimeric receptors link matrix binding to intracellular structures and signaling.'],['Histones','Histones organize nuclear DNA rather than binding matrix at the cell surface.'],['Connexins','Connexins form communication channels rather than principal fibronectin receptors.'],['Albumin','Albumin is a soluble plasma protein rather than a transmembrane adhesion receptor.']],
'Integrins bind extracellular matrix and connect through adaptor proteins to the cytoskeleton. Engagement coordinates adhesion, force transmission, and environmental signaling. Blocking fibronectin-integrin interaction therefore changes shape and migration without requiring destruction of cell-cell junctions.','Explain integrin coupling between matrix attachment and cell behavior.','leukocyte adhesion deficiency'),
q('Biochemistry','General Principles','Cadherin extracellular calcium dependence',2,'Chelating extracellular calcium disrupts epithelial cell-cell adhesion before cells die. Which adhesion family directly requires calcium to maintain its extracellular adhesive conformation?',[
['Cadherins','Calcium stabilizes extracellular cadherin domains used for homophilic adhesion.'],['Cytosolic actin alone','Actin is not the extracellular calcium-dependent adhesion receptor.'],['DNA polymerases','DNA synthesis enzymes do not mediate epithelial surface adhesion.'],['Hemoglobin','Hemoglobin transports oxygen rather than forming epithelial adhesion complexes.']],
'Cadherins mediate calcium-dependent cell-cell adhesion. Extracellular calcium stabilizes their domain arrangement and adhesive interactions, so chelation can weaken junctions without generalized cell death. This direct structural requirement differs from calcium acting solely as an intracellular messenger.','Explain extracellular calcium dependence of cadherin-mediated adhesion.','integrin matrix attachment'),
q('Biochemistry','General Principles','Importin nuclear localization',2,'A large cytosolic protein gains a short basic amino-acid sequence and then accumulates in the nucleus. Which system recognizes the added nuclear targeting signal?',[
['Importin-dependent nuclear pore transport','Importins recognize localization signals and coordinate selective pore transit.'],['Mannose-6-phosphate receptor sorting','This pathway targets lysosomal enzymes rather than large nuclear proteins.'],['Signal recognition particle ER docking','An ER signal sequence directs a different intracellular destination.'],['Passive diffusion across nuclear lipid','Large proteins enter through pores rather than directly through the lipid bilayer.']],
'Basic nuclear localization sequences bind importin transport receptors. Cargo traverses nuclear pore complexes, with directionality supported by the Ran GTPase system. A targeting sequence can therefore change protein distribution without requiring membrane rupture or direct diffusion across nuclear lipid.','Associate basic nuclear targeting sequences with importin-mediated transport.','ER signal recognition particle'),
q('Biochemistry','General Principles','Alternative exon selection',2,'Two tissues produce different proteins from one gene by retaining different internal exons in mature messenger RNA. Which process accounts for the isoforms?',[
['Alternative RNA splicing','Regulated exon selection generates distinct transcripts from one primary RNA.'],['Obligatory coding DNA mutation','Different exon inclusion does not require tissue-specific DNA sequence changes.'],['Mitochondrial fission','Organelle division does not directly select nuclear pre-mRNA exons.'],['Removal of every coding exon','Complete loss of coding exons would not explain functional protein isoforms.']],
'Alternative splice-site choices can produce distinct mature RNAs from one primary transcript. Tissue-specific splicing factors regulate inclusion or exclusion of particular exons. Proteomic diversity therefore increases without requiring a different genomic coding sequence in each tissue.','Distinguish alternative splicing from DNA mutation as a source of protein isoforms.','DNA repair defects'),
q('Biochemistry','General Principles','MicroRNA repression',2,'A small noncoding RNA pairs imperfectly with a messenger RNA three-prime untranslated region. Protein output falls without a DNA change. Which mechanism is demonstrated?',[
['MicroRNA-mediated post-transcriptional repression','MicroRNA complexes reduce translation and can destabilize target transcripts.'],['Permanent deletion of the gene','The regulation is described without alteration of the DNA sequence.'],['Protein synthesis by the small RNA itself','The small RNA regulates a target rather than encoding the measured protein.'],['Conversion of RNA into a chromosome','Ordinary microRNA repression does not require this conversion.']],
'MicroRNAs guide silencing complexes to partially complementary transcripts. Binding can reduce translation and promote deadenylation or decay. This post-transcriptional regulation changes protein abundance while leaving the underlying genomic sequence unchanged.','Explain microRNA-mediated reduction of target protein output.','alternative splice isoforms'),
q('Biochemistry','General Principles','Histone acetylation charge',2,'A promoter becomes more accessible after nearby histone lysines are acetylated. Which change helps explain weaker histone-DNA electrostatic interaction?',[
['Reduced positive charge of histone lysines','Acetylation neutralizes lysine charge and can favor chromatin accessibility.'],['Addition of new DNA bases','Histone acetylation modifies protein rather than adding DNA nucleotides.'],['Removal of every genomic nucleosome','A local modification does not require genome-wide nucleosome elimination.'],['Covalent ligation of mRNA to the promoter','RNA ligation is not the mechanism of histone charge neutralization.']],
'Histone lysine acetylation neutralizes positive charge and can recruit acetylation-recognizing proteins. These effects often favor accessible chromatin and transcription. The modification regulates gene expression rather than changing the sequence of the DNA encoding that gene.','Relate histone acetylation to chromatin accessibility through charge alteration.','genomic imprinting'),
q('Biochemistry','General Principles','Topoisomerase torsional control',2,'A replication fork encounters positive supercoils generated ahead of its helicase. Which enzyme activity normally relieves this accumulating torsional stress?',[
['Transient DNA cleavage and resealing by topoisomerase','Controlled strand rotation or passage relieves supercoils while preserving continuity.'],['Ribosomal peptide-bond formation','Translation does not directly release torsional stress in DNA.'],['Telomerase extension of internal DNA','Telomerase acts at chromosome termini rather than relaxing fork supercoils.'],['Poly-A addition to DNA','Polyadenylation is RNA processing rather than DNA torsional control.']],
'Helicase unwinding alters the topology of DNA ahead of a fork. Topoisomerases create transient controlled strand breaks, permit rotation or passage, and reseal the DNA. This relieves torsion and supports replication without requiring uncontrolled chromosome fragmentation.','Identify topoisomerase activity as the solution to replication-associated torsion.','DNA repair pathway recognition'),
q('Biochemistry','General Principles','Lagging strand polymerase direction',1,'Short DNA fragments are synthesized away from a replication fork and later joined. Which polymerase property makes this discontinuous strand synthesis necessary?',[
['DNA extension occurs five-prime to three-prime','Antiparallel templates require discontinuous copying on one side of the fork.'],['DNA extension occurs only three-prime to five-prime','This reverses the normal chemical direction of DNA polymerization.'],['Both DNA templates run in parallel','The paired strands are antiparallel rather than parallel.'],['Ligase inserts all replicated nucleotides','Ligase joins breaks and does not replace the replicative polymerase.']],
'DNA polymerases add nucleotides to a growing strand at its three-prime hydroxyl. Because DNA templates are antiparallel, one daughter strand must be made discontinuously as Okazaki fragments. Primer replacement and ligation later produce a continuous lagging strand.','Explain Okazaki fragments from polymerase directionality and antiparallel templates.','topoisomerase function'),
q('Biochemistry','General Principles','Telomerase RNA template',2,'A dividing cell maintains chromosome ends using a reverse transcriptase that carries its own RNA component. What direct role does that RNA play?',[
['Template for telomeric DNA repeat addition','Telomerase copies its RNA template to extend chromosome termini.'],['Primer for all mitochondrial translation','The RNA belongs to telomerase rather than mitochondrial protein synthesis.'],['Protease that removes histones','Telomerase RNA is not a principal histone-degrading enzyme.'],['ER targeting signal for collagen','An RNA template is not a secretory peptide targeting sequence.']],
'Telomerase is a ribonucleoprotein reverse transcriptase whose RNA provides a template for adding telomeric DNA repeats. Extension of chromosome termini supports subsequent complementary synthesis. This helps address sequence loss associated with conventional replication of linear chromosome ends.','Identify the template role of telomerase RNA.','lagging strand DNA synthesis'),
q('Pathology','General Principles','Cellular hypertrophy adaptation',1,'Cardiac myocytes enlarge during sustained increased workload without a corresponding rise in their number. Which cellular adaptation is represented by this finding?',[
['Hypertrophy','Hypertrophy increases individual cell size through greater structural content.'],['Hyperplasia','Hyperplasia increases cell number rather than individual size alone.'],['Metaplasia','Metaplasia replaces one differentiated cell type with another.'],['Dysplasia','Dysplasia is disordered maturation and atypia rather than simple size adaptation.']],
'Hypertrophy enlarges individual cells through increased protein and organelle content. It can increase organ mass in tissues with limited proliferative capacity, including adult myocardium. Hyperplasia instead increases cell number, while metaplasia changes differentiated phenotype.','Distinguish hypertrophy from hyperplasia and metaplasia.','Barrett metaplasia'),
q('Pathology','General Principles','Disuse atrophy protein balance',2,'An immobilized limb loses muscle mass over several weeks without widespread myocyte necrosis. Which process directly contributes to smaller surviving fibers?',[
['Increased degradation relative to protein synthesis','Altered protein balance removes contractile material from existing fibers.'],['Malignant conversion of every muscle fiber','Atrophy does not require transformation into a malignant tissue.'],['Obligatory calcium crystal deposition','Routine disuse wasting does not require cellular calcification.'],['Proliferation of additional identical fibers','More fibers would not explain the observed reduction in muscle mass.']],
'Disuse reduces mechanical and trophic support for muscle maintenance. Reduced synthesis and increased proteolysis, including ubiquitin-proteasome activity, decrease fiber size. Viability can persist, distinguishing adaptive atrophy from necrosis and complete loss of the cell.','Explain disuse atrophy through altered cellular protein balance.','coagulative necrosis'),
q('Pathology','General Principles','Hydropic reversible injury',2,'Cells briefly deprived of oxygen become swollen but recover after oxygen is restored. Which early biochemical failure most directly promotes this reversible swelling?',[
['Reduced ATP-dependent ion pumping','Intracellular sodium accumulation draws water into the energy-depleted cell.'],['Complete digestion of nuclear DNA','Extensive nuclear destruction indicates irreversible rather than reversible injury.'],['Immediate replacement by collagen scar','Fibrosis cannot explain rapid recovery of the same swollen cells.'],['Loss of every membrane lipid','Total membrane disintegration would prevent the stated recovery.']],
'ATP depletion impairs sodium-potassium ATPase activity and disrupts ion balance. Sodium and water accumulate intracellularly, producing hydropic swelling. If oxygen returns before irreversible mitochondrial and membrane damage, pumping can recover and cellular volume can normalize.','Link reversible hypoxic swelling to ATP-dependent pump impairment.','ischemic necrosis morphology'),
q('Pathology','General Principles','Reperfusion oxidant injury',2,'A tissue develops additional damage when blood flow returns after ischemia. Which process can contribute specifically to injury during the reperfusion phase?',[
['Reactive oxygen species generation','Restored oxygen can fuel oxidant production and damage stressed membranes.'],['Permanent absence of oxygen despite restored flow','Reperfusion normally supplies oxygen rather than preserving complete absence.'],['Instant regeneration of all necrotic cells','Restoring flow does not immediately reverse established necrotic death.'],['Scar collagen becoming viable myocardium','Collagen does not directly transform into functional parenchymal cells.']],
'Reperfusion supplies oxygen but can also promote reactive oxygen species, calcium loading, and inflammation. These processes may damage membranes and mitochondria already stressed by ischemia. Restoration of flow therefore has benefit while also introducing specific mechanisms of added injury.','Explain reactive oxygen species as a contributor to reperfusion injury.','electron transport inhibition'),
q('Pathology','General Principles','Autophagic nutrient recycling',2,'A starved cell encloses cytoplasm in double-membrane vesicles that later fuse with lysosomes. Which adaptive process recycles this intracellular material?',[
['Macroautophagy','Autophagosomes deliver cytoplasmic components to lysosomes for degradation.'],['LDL receptor uptake alone','That imports extracellular particles rather than enclosing existing cytoplasm.'],['Extracellular collagen cross-linking','Matrix assembly does not describe lysosomal intracellular recycling.'],['Mitotic chromosome segregation','Spindle movement does not form the degradative vesicles described.']],
'Macroautophagy sequesters cytoplasmic components within double-membrane autophagosomes. Lysosomal fusion permits degradation and reuse of molecular building blocks under nutrient stress. It can support cell survival, although consequences vary with context and injury severity.','Identify autophagic recycling of cytoplasm during nutrient deprivation.','proteasomal degradation'),
q('Pathology','General Principles','Senescence versus quiescence',2,'A fibroblast remains metabolically active but durably stops dividing after many replications. Which state best describes this viable, stable proliferative arrest?',[
['Cellular senescence','Senescence is durable growth arrest despite ongoing metabolic activity.'],['Necrosis','Necrosis is cell death rather than persistent viable growth arrest.'],['Transient quiescence alone','Quiescence is generally reversible unlike the durable arrest described.'],['Unrestricted malignant proliferation','The observation is cessation rather than acceleration of cell division.']],
'Senescence is stable cell-cycle arrest after stresses such as telomere attrition. The cell remains alive and can retain metabolic and secretory activity. It differs from reversible quiescence and from apoptosis or necrosis, which eliminate the viable cell rather than merely stop proliferation.','Distinguish senescence from reversible quiescence and cell death.','apoptosis pathways'),
q('Pathology','General Principles','Lipofuscin residual pigment',1,'An older adult has fine yellow-brown perinuclear granules in viable cells. The material consists of residual lipid-protein oxidation products. Which pigment is present?',[
['Lipofuscin','Lipofuscin accumulates as incompletely degraded wear-associated intracellular material.'],['Hemosiderin','Hemosiderin represents stored iron rather than lipid-protein residual products.'],['Melanin in every case','Melanin forms through a different pigment synthesis pathway.'],['Bilirubin crystals alone','Bilirubin is not the characteristic perinuclear wear pigment described.']],
'Lipofuscin contains residual lipid-protein material associated with oxidation and incomplete lysosomal degradation. It accumulates in many long-lived cells with age. Its presence alone does not establish cell death or iron overload, despite a brown color shared with other pigments.','Recognize lipofuscin as residual oxidation-associated intracellular pigment.','dystrophic calcification'),
q('Pathology','General Principles','Hemosiderin iron detection',1,'Macrophages in an old hemorrhage contain coarse golden-brown granules. Which stain most directly demonstrates the ferric iron within this stored pigment?',[
['Prussian blue','Prussian blue identifies ferric iron in hemosiderin deposits.'],['Congo red','Congo red detects amyloid rather than specifically identifying stored iron.'],['Acid-fast stain','Acid-fast staining identifies characteristic lipid-rich microbial walls.'],['Periodic acid-Schiff as an iron-specific test','PAS highlights selected carbohydrates and is not specific for iron.']],
'After hemorrhage, macrophages degrade red cells and retain excess iron as hemosiderin. Ferric iron reacts with Prussian blue reagents. Chemical staining helps distinguish hemosiderin from lipofuscin or melanin because their similar colors alone do not identify their composition.','Select Prussian blue to demonstrate hemosiderin ferric iron.','amyloid Congo red staining'),
q('Pathology','General Principles','Metastatic mineral calcification',2,'Persistent marked hypercalcemia is followed by calcium deposition in previously viable tissues. Which process best describes this systemic mineral deposition pattern?',[
['Metastatic calcification','Systemic mineral imbalance permits deposits without preceding local necrosis.'],['Dystrophic calcification only','Dystrophic deposits form in injured tissue often with normal serum calcium.'],['Normal ossification in each organ','Calcium deposits do not automatically contain organized bone architecture.'],['Melanin synthesis','Melanin is an organic pigment rather than deposited calcium salts.']],
'Metastatic calcification results from systemic calcium or phosphate disturbances and may affect otherwise viable tissue. Dystrophic calcification instead favors injured or necrotic tissue despite often normal serum minerals. Biochemical context therefore helps distinguish the deposition mechanisms.','Distinguish systemic metastatic calcification from dystrophic deposits.','dystrophic calcification'),
q('Pathology','General Principles','Fat necrosis saponification',2,'After pancreatic enzyme leakage into adjacent fat, chalky deposits appear in the damaged tissue. Which chemical process most directly produces these deposits?',[
['Calcium binding to liberated fatty acids','Lipase releases fatty acids that combine with calcium into insoluble soaps.'],['Triglyceride conversion directly into amyloid','Amyloid is fibrillar protein rather than a direct triglyceride product.'],['Accumulation of red-cell iron alone','Hemosiderin does not explain chalky calcium-rich fat deposits.'],['Formation of mature cortical bone throughout','Saponification produces salts rather than organized cortical bone.']],
'Lipase hydrolyzes triglycerides in injured adipocytes, releasing fatty acids. Binding of calcium to these products creates insoluble soaps and chalky areas of enzymatic fat necrosis. This saponification differs from iron pigment deposition, amyloid formation, and true ossification.','Explain chalky fat necrosis through calcium-fatty-acid soap formation.','pancreatitis diagnostic reasoning'),
q('Pathology','General Principles','Selectin inflammatory rolling',2,'In an inflamed venule, neutrophils make brief low-affinity contacts and roll before firmly adhering. Which adhesion family principally mediates this rolling phase?',[
['Selectins','Selectins form transient bonds with carbohydrate ligands during rolling.'],['High-affinity integrins alone','Activated integrins chiefly mediate the later firm adhesion step.'],['Collagen triple helices','Collagen is matrix rather than the endothelial rolling receptor family.'],['Connexins','Connexins form communication channels rather than rolling interactions.']],
'Selectins bind leukocyte carbohydrate ligands through transient interactions under flow. Slowing the cells allows chemokine-driven integrin activation and subsequent firm arrest. Rolling and firm adhesion therefore use distinct molecular steps within the same recruitment sequence.','Separate selectin-mediated rolling from integrin-mediated firm adhesion.','leukocyte adhesion deficiency'),
q('Pathology','General Principles','PECAM junctional diapedesis',2,'After firm adhesion, a neutrophil moves between endothelial cells into inflamed tissue. Which adhesion molecule participates in this junctional transmigration?',[
['PECAM-1 CD31','PECAM-1 participates in leukocyte passage across endothelial junctions.'],['Hemoglobin A','Hemoglobin carries oxygen rather than mediating leukocyte junctional passage.'],['Thyroglobulin','This thyroid storage protein is not a transmigration adhesion molecule.'],['Intrinsic factor','This gastric binding protein does not guide leukocytes through endothelium.']],
'Leukocyte emigration proceeds through rolling, adhesion, and diapedesis. PECAM-1 at endothelial junctions and on leukocytes contributes to the transmigration step. Chemotactic cues then guide movement in tissue, separating this junctional event from earlier vascular rolling.','Associate PECAM-1 with leukocyte diapedesis through endothelial junctions.','selectin rolling'),
q('Pathology','General Principles','Granulation versus granuloma',1,'A healing wound contains many new small vessels, proliferating fibroblasts, and loose matrix. Which term describes this vascular repair tissue?',[
['Granulation tissue','New capillaries and fibroblasts in loose matrix define granulation tissue.'],['Granuloma','A granuloma is organized macrophage-rich inflammation rather than this repair bed.'],['Mature dense scar alone','A mature scar is less vascular and more collagen-dense than this tissue.'],['Coagulative necrosis','Necrosis is tissue death rather than viable angiogenic repair.']],
'Granulation tissue combines angiogenesis, fibroblast proliferation, and early extracellular matrix deposition during repair. It later matures toward a less vascular scar. Similar terminology should not obscure its difference from granulomas, which are organized collections of activated macrophages.','Recognize granulation tissue and distinguish it from granulomatous inflammation.','granulomatous inflammation'),
q('Pathology','General Principles','Carcinoma basement membrane breach',2,'An epithelial lesion has severe cytologic atypia but remains above an intact basement membrane. Which finding would establish local stromal invasion?',[
['Malignant cells crossing the basement membrane','Penetration into the underlying stroma defines local invasive carcinoma.'],['Larger nuclei confined to the epithelium','Cytologic atypia alone can occur in carcinoma in situ.'],['More epithelial mitoses without stromal entry','Increased proliferation does not itself demonstrate basement membrane breach.'],['Darker surface pigment alone','Pigment intensity does not establish malignant stromal penetration.']],
'Carcinoma in situ has malignant epithelial cytology without penetration through the basement membrane. Stromal entry establishes invasion and changes access to the surrounding microenvironment and potentially lymphovascular channels. Atypia or mitotic activity alone does not prove this transition.','Use basement membrane breach to distinguish invasive from in situ carcinoma.','metaplasia and tumor suppression'),
];
